<body>
  <div class="app">
    <header>
      <h1>📝 Todo App</h1>
      <p>Stay organized, get things done</p>
    </header>

    <div class="input-row">
      <input type="text" id="todo-input" placeholder="What needs to be done?" autocomplete="off" />
      <button id="add-btn">Add</button>
    </div>

    <div class="filters">
      <button data-filter="all" class="active">All</button>
      <button data-filter="active">Active</button>
      <button data-filter="completed">Completed</button>
      <span class="count" id="count"></span>
    </div>

    <ul class="todo-list" id="todo-list"></ul>
    <div class="empty" id="empty" style="display:none;">No todos here.</div>

    <div class="footer">
      <span id="remaining"></span>
      <button id="clear-completed">Clear completed</button>
    </div>
  </div>

<script>
(function () {
  'use strict';

  const STORAGE_KEY = 'todo_app_items_v1';
  const FILTER_KEY = 'todo_app_filter_v1';

  /** @type {{id:string,text:string,done:boolean,createdAt:number}[]} */
  let todos = loadTodos();
  let currentFilter = loadFilter();

  const $input = document.getElementById('todo-input');
  const $addBtn = document.getElementById('add-btn');
  const $list = document.getElementById('todo-list');
  const $empty = document.getElementById('empty');
  const $count = document.getElementById('count');
  const $remaining = document.getElementById('remaining');
  const $clearBtn = document.getElementById('clear-completed');
  const $filterBtns = document.querySelectorAll('.filters button[data-filter]');

  function loadTodos() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      console.warn('Failed to load todos:', e);
      return [];
    }
  }

  function saveTodos() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      console.warn('Failed to save todos:', e);
    }
  }

  function loadFilter() {
    const v = localStorage.getItem(FILTER_KEY);
    return v === 'active' || v === 'completed' ? v : 'all';
  }

  function saveFilter() {
    localStorage.setItem(FILTER_KEY, currentFilter);
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function addTodo(text) {
    const trimmed = text.trim();
    if (!trimmed) return;
    todos.push({
      id: uid(),
      text: trimmed,
      done: false,
      createdAt: Date.now()
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    const t = todos.find(x => x.id === id);
    if (!t) return;
    t.done = !t.done;
    saveTodos();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(x => x.id !== id);
    saveTodos();
    render();
  }

  function clearCompleted() {
    const before = todos.length;
    todos = todos.filter(x => !x.done);
    if (todos.length !== before) {
      saveTodos();
      render();
    }
  }

  function setFilter(f) {
    if (f !== 'all' && f !== 'active' && f !== 'completed') return;
    currentFilter = f;
    saveFilter();
    render();
  }

  function getFiltered() {
    if (currentFilter === 'active') return todos.filter(t => !t.done);
    if (currentFilter === 'completed') return todos.filter(t => t.done);
    return todos.slice();
  }

  function render() {
    // Filter buttons
    $filterBtns.forEach(btn => {
      btn.classList.toggle('active', btn.dataset.filter === currentFilter);
    });

    const filtered = getFiltered();

    // List
    $list.innerHTML = '';
    if (filtered.length === 0) {
      $empty.style.display = 'block';
      const msg = todos.length === 0
        ? 'No todos yet — add one above!'
        : 'No ' + currentFilter + ' todos.';
      $empty.textContent = msg;
    } else {
      $empty.style.display = 'none';
      const frag = document.createDocumentFragment();
      filtered.forEach(t => {
        const li = document.createElement('li');
        if (t.done) li.classList.add('done');

        const cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.checked = t.done;
        cb.setAttribute('aria-label', 'Mark complete: ' + t.text);
        cb.addEventListener('change', () => toggleTodo(t.id));

        const span = document.createElement('span');
        span.className = 'text';
        span.textContent = t.text;

        const del = document.createElement('button');
        del.className = 'delete';
        del.type = 'button';
        del.setAttribute('aria-label', 'Delete: ' + t.text);
        del.textContent = '×';
        del.addEventListener('click', () => deleteTodo(t.id));

        li.appendChild(cb);
        li.appendChild(span);
        li.appendChild(del);
        frag.appendChild(li);
      });
      $list.appendChild(frag);
    }

    // Counts
    const activeCount = todos.filter(t => !t.done).length;
    const total = todos.length;
    $count.textContent = total + (total === 1 ? ' item' : ' items');
    $remaining.textContent = activeCount + (activeCount === 1 ? ' item left' : ' items left');

    // Clear button
    const hasCompleted = todos.some(t => t.done);
    $clearBtn.disabled = !hasCompleted;
  }

  // Event wiring
  $addBtn.addEventListener('click', () => {
    addTodo($input.value);
    $input.value = '';
    $input.focus();
  });

  $input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      addTodo($input.value);
      $input.value = '';
    }
  });

  $filterBtns.forEach(btn => {
    btn.addEventListener('click', () => setFilter(btn.dataset.filter));
  });

  $clearBtn.addEventListener('click', clearCompleted);

  // Initial render
  render();
  $input.focus();
})();
</script>
</body>
</html>
